package main
import("context";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();ids:=[]int64{348,349,350,381,382,384,402,403,404,408,410,411,412,414,432,433,434,435,436,442};rows,e:=p.Query(c,`select r.id,r.status,coalesce(r.capture_via,''),coalesce(r.preferred_relay_group_id,0),(select count(*) from recording_jobs j where j.recording_id=r.id and j.status='pending'),(select count(*) from recording_jobs j where j.recording_id=r.id and j.status='leased' and j.lease_expires_at>now()),(select count(*) from recording_jobs j where j.recording_id=r.id and j.handoff_until>now()),(select count(*) from recording_upload_intents u where u.recording_id=r.id and u.status='pending' and u.expires_at>now()) from recordings r where r.account_id=47 and r.id=any($1::bigint[]) order by r.id`,ids);if e!=nil{panic(e)};defer rows.Close();var bad int;for rows.Next(){var id,grp,pending,leased,handoff,intents int;var st,via string;if e:=rows.Scan(&id,&st,&via,&grp,&pending,&leased,&handoff,&intents);e!=nil{panic(e)};fmt.Printf("GATE %d status=%s via=%s group=%d p=%d l=%d h=%d i=%d\n",id,st,via,grp,pending,leased,handoff,intents);if pending+leased+handoff+intents>0{bad++}};fmt.Printf("GATE_SUMMARY selected=%d busy=%d\n",20,bad)}
